// 26 Crockford base32 characters; the first one is limited to 0-7 because the timestamp fits in 48 bits.
const ULID_PATTERN = /^[0-7][0-9A-HJKMNP-TV-Z]{25}$/;

/** True when `value` has the shape of an id generated by the IdGenerator port. */
export function isUlid(value: string): boolean {
  return ULID_PATTERN.test(value);
}
